import { useState, useEffect } from "react";
import { supabase } from "../api";
import { motion, AnimatePresence } from "framer-motion";

function AdminPage() {
  const [categories, setCategories] = useState([]);
  const [subCategories, setSubCategories] = useState([]);
  const [selectedCategory, setSelectedCategory] = useState("");
  const [selectedSubCategory, setSelectedSubCategory] = useState("");
  const [canevasList, setCanevasList] = useState([]);

  const [newCategory, setNewCategory] = useState("");
  const [newSubCategory, setNewSubCategory] = useState("");
  const [newCanevasTitle, setNewCanevasTitle] = useState("");
  const [newCanevasContent, setNewCanevasContent] = useState("");

  const [editingCanevasId, setEditingCanevasId] = useState(null);
  const [editedTitle, setEditedTitle] = useState("");
  const [editedContent, setEditedContent] = useState("");

  const [users, setUsers] = useState([]);
  const [showUserManagement, setShowUserManagement] = useState(false);

  const [suggestions, setSuggestions] = useState([]);
  const [showSuggestionsSection, setShowSuggestionsSection] = useState(false);

  const [newsList, setNewsList] = useState([]);
  const [newNewsTitle, setNewNewsTitle] = useState("");
  const [newNewsContent, setNewNewsContent] = useState("");
  const [showNewsSection, setShowNewsSection] = useState(false);

  // Secteur (sert à filtrer l’édition)
  const [adminSector, setAdminSector] = useState("particulier");

  // Sections rétractables
  const [showCanevasSection, setShowCanevasSection] = useState(false);

  // Reset requests
  const [resetRequests, setResetRequests] = useState([]);

  // ✅ MODAL "ANTI-DESTRUCTION" (taper SUPPRIMER)
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [confirmText, setConfirmText] = useState("");
  const [confirmError, setConfirmError] = useState("");
  const [confirmInfo, setConfirmInfo] = useState({
    title: "",
    message: "",
    onConfirm: async () => {},
  });

  const closeConfirm = () => {
    setConfirmOpen(false);
    setConfirmText("");
    setConfirmError("");
    setConfirmInfo({ title: "", message: "", onConfirm: async () => {} });
  };

  const openConfirm = ({ title, message, onConfirm }) => {
    setConfirmInfo({ title, message, onConfirm });
    setConfirmText("");
    setConfirmError("");
    setConfirmOpen(true);
  };

  // ✅ Helpers: compter le "contenu réel" (ignorer les placeholders)
  const countCategoryRealContent = async (sector, category) => {
    // Canevas réels: title != "-"
    const { count: canevasCount, error: cErr } = await supabase
      .from("canevas")
      .select("id", { count: "exact", head: true })
      .eq("sector", sector)
      .eq("category", category)
      .neq("title", "-");

    if (cErr) throw cErr;

    // Sous-catégories réelles: subCategory != "-"
    const { data: subData, error: sErr } = await supabase
      .from("canevas")
      .select("subCategory")
      .eq("sector", sector)
      .eq("category", category)
      .neq("subCategory", "-");

    if (sErr) throw sErr;

    const uniqueSubs = [
      ...new Set((subData || []).map((x) => x.subCategory).filter(Boolean)),
    ];

    return { canevasCount: canevasCount || 0, subCategoryCount: uniqueSubs.length };
  };

  const countSubCategoryRealContent = async (sector, category, subCategory) => {
    const { count, error } = await supabase
      .from("canevas")
      .select("id", { count: "exact", head: true })
      .eq("sector", sector)
      .eq("category", category)
      .eq("subCategory", subCategory)
      .neq("title", "-");

    if (error) throw error;
    return count || 0;
  };

  const fetchUsers = async () => {
    const { data, error } = await supabase
      .from("users")
      .select("id, email, isApproved, role, last_active");

    if (error) {
      console.error(error);
      alert("❌ Erreur chargement utilisateurs.");
      return;
    }
    setUsers(data || []);
  };

  const fetchSuggestions = async () => {
    const { data, error } = await supabase
      .from("suggestions")
      .select("id, category, content, created_at, users(email)")
      .order("created_at", { ascending: false });

    if (error) {
      console.error(error);
      alert("❌ Erreur chargement suggestions.");
      return;
    }
    setSuggestions(data || []);
  };

  const fetchNews = async () => {
    const { data, error } = await supabase
      .from("news")
      .select("*")
      .order("created_at", { ascending: false });

    if (error) {
      console.error(error);
      alert("❌ Erreur chargement nouveautés.");
      return;
    }
    setNewsList(data || []);
  };

  const fetchResetRequests = async () => {
    const { data, error } = await supabase
      .from("password_reset_requests")
      .select("*")
      .order("requested_at", { ascending: false });

    if (error) {
      console.error(error);
      alert("❌ Erreur chargement demandes de reset.");
      return;
    }
    setResetRequests(data || []);
  };

  // Catégories filtrées par secteur
  const fetchCategories = async () => {
    const { data, error } = await supabase
      .from("canevas")
      .select("category")
      .eq("sector", adminSector);

    if (error) {
      console.error(error);
      alert("❌ Erreur chargement catégories.");
      return;
    }

    const unique = [...new Set((data || []).map((i) => i.category))].filter(Boolean);
    setCategories(unique);
  };

  // Sous-catégories filtrées par secteur + catégorie
  const fetchSubCategories = async () => {
    if (!selectedCategory) return;

    const { data, error } = await supabase
      .from("canevas")
      .select("subCategory")
      .eq("sector", adminSector)
      .eq("category", selectedCategory);

    if (error) {
      console.error(error);
      alert("❌ Erreur chargement sous-catégories.");
      return;
    }

    const unique = [...new Set((data || []).map((i) => i.subCategory))].filter(Boolean);
    setSubCategories(unique);
  };

  // Canevas filtrés par secteur + catégorie + sous-catégorie
  const fetchCanevas = async () => {
    if (!selectedCategory || !selectedSubCategory) return;

    const { data, error } = await supabase
      .from("canevas")
      .select("*")
      .eq("sector", adminSector)
      .eq("category", selectedCategory)
      .eq("subCategory", selectedSubCategory);

    if (error) {
      console.error(error);
      alert("❌ Erreur chargement canevas.");
      return;
    }

    setCanevasList(data || []);
  };

  // Initial load
  useEffect(() => {
    fetchCategories();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Quand on change de secteur : reset + reload
  useEffect(() => {
    setSelectedCategory("");
    setSelectedSubCategory("");
    setSubCategories([]);
    setCanevasList([]);
    cancelEditing();
    fetchCategories();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [adminSector]);

  useEffect(() => {
    fetchSubCategories();
    setSelectedSubCategory("");
    setCanevasList([]);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedCategory]);

  useEffect(() => {
    fetchCanevas();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedSubCategory]);

  useEffect(() => {
    if (showSuggestionsSection) fetchSuggestions();
  }, [showSuggestionsSection]);

  useEffect(() => {
    if (showNewsSection) fetchNews();
  }, [showNewsSection]);

  useEffect(() => {
    if (showUserManagement) {
      fetchUsers();
      fetchResetRequests();
    }
  }, [showUserManagement]);

  // INSERT Catégorie
  const addCategory = async () => {
    if (!newCategory.trim()) return;

    const { error } = await supabase.from("canevas").insert([
      {
        sector: adminSector,
        category: newCategory.trim(),
        subCategory: "-",
        title: "-",
        content: "-",
      },
    ]);

    if (error) {
      console.error(error);
      alert("❌ Impossible d'ajouter la catégorie (Supabase a refusé).");
      return;
    }

    setNewCategory("");
    fetchCategories();
  };

  // ✅ DELETE Catégorie (avec confirmation renforcée si grosse suppression)
  const deleteCategory = async (cat) => {
    try {
      const { canevasCount, subCategoryCount } = await countCategoryRealContent(adminSector, cat);

      const isRisky = canevasCount > 1 || subCategoryCount > 1;

      const doDelete = async () => {
        const { error } = await supabase
          .from("canevas")
          .delete()
          .eq("sector", adminSector)
          .eq("category", cat);

        if (error) {
          console.error(error);
          alert("❌ Suppression refusée.");
          return;
        }

        fetchCategories();
        setSelectedCategory("");
        setSelectedSubCategory("");
        setSubCategories([]);
        setCanevasList([]);
        closeConfirm();
      };

      if (!isRisky) {
        const confirmDelete = window.confirm(
          `⚠️ Supprimer la catégorie "${cat}" dans le secteur "${adminSector}" ?`
        );
        if (!confirmDelete) return;
        await doDelete();
        return;
      }

      openConfirm({
        title: `Suppression de la catégorie "${cat}"`,
        message: `Cette catégorie contient ${subCategoryCount} sous-catégorie(s) et ${canevasCount} canevas.\n\nTapez SUPPRIMER pour confirmer.`,
        onConfirm: doDelete,
      });
    } catch (e) {
      console.error(e);
      alert("❌ Erreur lors de la vérification avant suppression.");
    }
  };

  // INSERT Sous-catégorie
  const addSubCategory = async () => {
    if (!selectedCategory || !newSubCategory.trim()) return;

    const { error } = await supabase.from("canevas").insert([
      {
        sector: adminSector,
        category: selectedCategory,
        subCategory: newSubCategory.trim(),
        title: "-",
        content: "-",
      },
    ]);

    if (error) {
      console.error(error);
      alert("❌ Impossible d'ajouter la sous-catégorie.");
      return;
    }

    setNewSubCategory("");
    fetchSubCategories();
  };

  // ✅ DELETE Sous-catégorie (avec confirmation renforcée si grosse suppression)
  const deleteSubCategory = async (sub) => {
    try {
      const canevasCount = await countSubCategoryRealContent(
        adminSector,
        selectedCategory,
        sub
      );

      const isRisky = canevasCount > 1;

      const doDelete = async () => {
        const { error } = await supabase
          .from("canevas")
          .delete()
          .eq("sector", adminSector)
          .eq("category", selectedCategory)
          .eq("subCategory", sub);

        if (error) {
          console.error(error);
          alert("❌ Suppression refusée.");
          return;
        }

        fetchSubCategories();
        setSelectedSubCategory("");
        setCanevasList([]);
        closeConfirm();
      };

      if (!isRisky) {
        const confirmDelete = window.confirm(
          `⚠️ Supprimer la sous-catégorie "${sub}" dans "${selectedCategory}" (${adminSector}) ?`
        );
        if (!confirmDelete) return;
        await doDelete();
        return;
      }

      openConfirm({
        title: `Suppression de la sous-catégorie "${sub}"`,
        message: `Cette sous-catégorie contient ${canevasCount} canevas.\n\nTapez SUPPRIMER pour confirmer.`,
        onConfirm: doDelete,
      });
    } catch (e) {
      console.error(e);
      alert("❌ Erreur lors de la vérification avant suppression.");
    }
  };

  // INSERT Canevas
  const addCanevas = async () => {
    if (!selectedCategory || !selectedSubCategory || !newCanevasTitle.trim()) return;

    const { error } = await supabase.from("canevas").insert([
      {
        sector: adminSector,
        category: selectedCategory,
        subCategory: selectedSubCategory,
        title: newCanevasTitle.trim(),
        content: newCanevasContent,
      },
    ]);

    if (error) {
      console.error(error);
      alert("❌ Impossible d'ajouter le canevas.");
      return;
    }

    setNewCanevasTitle("");
    setNewCanevasContent("");
    fetchCanevas();
  };

  // DELETE Canevas
  const deleteCanevas = async (id) => {
    const confirmDelete = window.confirm("⚠️ Supprimer ce canevas ?");
    if (!confirmDelete) return;

    const { error } = await supabase
      .from("canevas")
      .delete()
      .eq("sector", adminSector)
      .eq("id", id);

    if (error) {
      console.error(error);
      alert("❌ Suppression refusée.");
      return;
    }

    fetchCanevas();
  };

  const startEditing = (canevas) => {
    setEditingCanevasId(canevas.id);
    setEditedTitle(canevas.title);
    setEditedContent(canevas.content);
  };

  const cancelEditing = () => {
    setEditingCanevasId(null);
    setEditedTitle("");
    setEditedContent("");
  };

  // UPDATE Canevas
  const saveCanevasChanges = async () => {
    if (!editedTitle.trim()) {
      alert("Le titre ne peut pas être vide.");
      return;
    }

    const { error } = await supabase
      .from("canevas")
      .update({ title: editedTitle.trim(), content: editedContent })
      .eq("sector", adminSector)
      .eq("id", editingCanevasId);

    if (error) {
      console.error(error);
      alert("❌ Erreur lors de la mise à jour.");
      return;
    }

    cancelEditing();
    fetchCanevas();
    alert("✅ Canevas mis à jour !");
  };

  const deleteSuggestion = async (id) => {
    const { error } = await supabase.from("suggestions").delete().eq("id", id);
    if (error) {
      console.error(error);
      alert("❌ Impossible de supprimer la suggestion.");
      return;
    }
    fetchSuggestions();
  };

  const approveUser = async (userId) => {
    const { error } = await supabase.from("users").update({ isApproved: true }).eq("id", userId);
    if (error) {
      console.error(error);
      alert("❌ Impossible d'approuver.");
      return;
    }
    fetchUsers();
  };

  const disapproveUser = async (userId) => {
    const { error } = await supabase.from("users").update({ isApproved: false }).eq("id", userId);
    if (error) {
      console.error(error);
      alert("❌ Impossible de désapprouver.");
      return;
    }
    fetchUsers();
  };

  const deleteResetRequest = async (id) => {
    const { error } = await supabase.from("password_reset_requests").delete().eq("id", id);
    if (error) {
      console.error(error);
      alert("❌ Impossible de supprimer la demande.");
      return;
    }
    fetchResetRequests();
  };

  const deleteUser = async (userId) => {
    const confirmDelete = window.confirm(
      "⚠️ Supprimer COMPLETEMENT ce compte (Auth + base de données) ?"
    );
    if (!confirmDelete) return;

    const { data, error } = await supabase.functions.invoke("delete-user", {
      body: { userId },
    });

    if (error) {
      console.error(error);
      alert("❌ Erreur lors de la suppression (Edge Function).");
      return;
    }

    if (!data?.success) {
      alert("❌ Suppression échouée.");
      return;
    }

    alert("✅ Compte supprimé (Auth + DB).");
    fetchUsers();
  };

  const promoteToAdmin = async (userId) => {
    const { error } = await supabase.from("users").update({ role: "admin" }).eq("id", userId);
    if (error) {
      console.error(error);
      alert("❌ Impossible de promouvoir.");
      return;
    }
    setTimeout(fetchUsers, 300);
  };

  const demoteToUser = async (userId) => {
    const { error } = await supabase.from("users").update({ role: "user" }).eq("id", userId);
    if (error) {
      console.error(error);
      alert("❌ Impossible de rétrograder.");
      return;
    }
    setTimeout(fetchUsers, 300);
  };

  const getLastActiveText = (timestamp) => {
    if (!timestamp) return { text: "Dernière activité inconnue", isOnline: false };

    const last = new Date(timestamp);
    const now = new Date();
    const diffMs = now - last;
    const diffMin = Math.floor(diffMs / 1000 / 60);

    if (diffMin < 1) return { text: "En ligne maintenant", isOnline: true };
    if (diffMin === 1) return { text: "Il y a 1 minute", isOnline: false };
    if (diffMin < 60) return { text: `Il y a ${diffMin} minutes`, isOnline: false };

    const diffHr = Math.floor(diffMin / 60);
    if (diffHr === 1) return { text: "Il y a 1 heure", isOnline: false };
    if (diffHr < 24) return { text: `Il y a ${diffHr} heures`, isOnline: false };

    const diffDay = Math.floor(diffHr / 24);
    if (diffDay === 1) return { text: "Il y a 1 jour", isOnline: false };
    return { text: `Il y a ${diffDay} jours`, isOnline: false };
  };

  return (
    <div className="p-10">
      <h1 className="text-3xl font-bold mb-6 text-blue-700">🛠️ Panneau d'administration</h1>

      <div className="flex flex-col sm:flex-row gap-4 mb-6">
        <button
          onClick={() => setShowUserManagement(!showUserManagement)}
          className="flex-1 bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600 transition"
        >
          {showUserManagement ? "🔽 Cacher la gestion des utilisateurs" : "👥 Gestion des utilisateurs"}
        </button>

        <button
          onClick={() => setShowCanevasSection(!showCanevasSection)}
          className="flex-1 bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600 transition"
        >
          {showCanevasSection ? "🔽 Cacher la gestion des canevas" : "📋 Gestion des canevas"}
        </button>

        <button
          onClick={() => setShowSuggestionsSection(!showSuggestionsSection)}
          className="flex-1 bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600 transition"
        >
          {showSuggestionsSection ? "🔽 Cacher les suggestions" : "📨 Gérer les suggestions"}
        </button>

        <button
          onClick={() => setShowNewsSection(!showNewsSection)}
          className="flex-1 bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600 transition"
        >
          {showNewsSection ? "🔽 Cacher les nouveautés" : "🆕 Gérer les nouveautés"}
        </button>
      </div>

      {/* Gestion utilisateurs */}
      <AnimatePresence>
        {showUserManagement && (
          <motion.div
            key="user-management"
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.3 }}
            className="mb-8 border rounded p-4 bg-gray-50 overflow-hidden"
          >
            <h2 className="text-xl font-bold mb-7">👤 Gestion des accès utilisateurs</h2>
            <h2 className="text-xl font-semibold mb-4">👥 Liste des utilisateurs</h2>

            <ul className="divide-y">
              {users.map((user) => {
                const { text, isOnline } = getLastActiveText(user.last_active);
                return (
                  <li key={user.id} className="flex justify-between items-center py-2 border-b">
                    <div className="flex justify-between w-full items-center">
                      <div>
                        <div className="flex items-center gap-2">
                          <span>{user.email}</span>
                          <span
                            className={`h-2 w-2 rounded-full ${isOnline ? "bg-green-500" : "bg-red-400"}`}
                            title={text}
                          ></span>
                        </div>
                        <div className="text-sm text-gray-500">{text}</div>
                      </div>

                      <div className="flex gap-2">
                        {user.isApproved ? (
                          <button
                            onClick={() => disapproveUser(user.id)}
                            className="bg-red-500 hover:bg-red-600 text-white px-2 py-1 rounded text-sm"
                          >
                            ❌ Désapprouver
                          </button>
                        ) : (
                          <button
                            onClick={() => approveUser(user.id)}
                            className="bg-green-600 hover:bg-green-700 text-white px-2 py-1 rounded text-sm"
                          >
                            ✅ Approuver
                          </button>
                        )}

                        {user.role !== "admin" ? (
                          <button
                            onClick={() => promoteToAdmin(user.id)}
                            className="bg-emerald-500 hover:bg-emerald-600 text-white px-2 py-1 rounded text-sm"
                          >
                            ⭐ Promouvoir admin
                          </button>
                        ) : (
                          <button
                            onClick={() => demoteToUser(user.id)}
                            className="bg-gray-400 hover:bg-gray-500 text-white px-2 py-1 rounded text-sm"
                          >
                            ⚙️ Rétrograder
                          </button>
                        )}

                        <button
                          onClick={() => deleteUser(user.id)}
                          className="bg-red-600 text-white px-2 py-1 rounded text-sm hover:bg-red-700"
                        >
                          🗑️ Supprimer
                        </button>
                      </div>
                    </div>
                  </li>
                );
              })}
            </ul>

            <div className="mb-6">
              <hr className="my-6 border-t" />
              <h3 className="text-lg font-semibold mb-3 border-b pb-2">
                📨 Demandes de réinitialisation de mot de passe
              </h3>

              {resetRequests.length === 0 ? (
                <p className="text-sm text-gray-500">Aucune demande pour le moment.</p>
              ) : (
                <ul className="divide-y bg-yellow-100 border border-yellow-400 rounded-md mb-4">
                  {resetRequests.map((req) => (
                    <li key={req.id} className="py-2 px-3 flex justify-between items-center">
                      <div>
                        <p className="font-medium">{req.email}</p>
                        <p className="text-xs text-gray-500">
                          Reçue le {new Date(req.requested_at).toLocaleString("fr-CA")}
                        </p>
                      </div>
                      <button
                        onClick={() => deleteResetRequest(req.id)}
                        className="bg-red-500 text-white px-3 py-1 rounded text-sm hover:bg-red-600"
                      >
                        Supprimer
                      </button>
                    </li>
                  ))}
                </ul>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Gestion canevas */}
      <div className="mb-6">
        <AnimatePresence>
          {showCanevasSection && (
            <motion.div
              key="canevas-section"
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: "auto" }}
              exit={{ opacity: 0, height: 0 }}
              transition={{ duration: 0.3 }}
              className="mt-4 overflow-hidden"
            >
              <div className="flex items-center gap-3 mb-4 p-3 border rounded bg-gray-50">
                <label className="font-semibold">Secteur :</label>
                <select
                  className="border rounded p-2"
                  value={adminSector}
                  onChange={(e) => setAdminSector(e.target.value)}
                >
                  <option value="particulier">Particulier</option>
                  <option value="entreprise">Entreprise</option>
                </select>
              </div>

              <h2 className="text-2xl font-semibold mb-2">📁 Catégories</h2>
              <input
                value={newCategory}
                onChange={(e) => setNewCategory(e.target.value)}
                placeholder="Nouvelle catégorie"
                className="p-2 border rounded w-full mb-2"
              />
              <button
                onClick={addCategory}
                className="bg-green-500 text-white px-4 py-2 rounded w-full mb-4"
              >
                ➕ Ajouter la catégorie
              </button>

              <ul className="mb-8">
                {categories.map((cat, idx) => (
                  <li key={idx} className="flex justify-between items-center border-b py-1">
                    <span>{cat}</span>
                    <button
                      onClick={() => deleteCategory(cat)}
                      className="text-red-600 hover:text-red-800"
                    >
                      Supprimer
                    </button>
                  </li>
                ))}
              </ul>

              <h2 className="text-2xl font-semibold mb-2">📂 Sous-catégories</h2>
              <select
                onChange={(e) => setSelectedCategory(e.target.value)}
                value={selectedCategory}
                className="p-2 border rounded w-full mb-2"
              >
                <option value="">Choisir une catégorie</option>
                {categories.map((cat, idx) => (
                  <option key={idx} value={cat}>
                    {cat}
                  </option>
                ))}
              </select>

              {selectedCategory && (
                <>
                  <select
                    onChange={(e) => setSelectedSubCategory(e.target.value)}
                    value={selectedSubCategory}
                    className="p-2 border rounded w-full mb-2"
                  >
                    <option value="">Choisir une sous-catégorie</option>
                    {subCategories.map((sub, idx) => (
                      <option key={idx} value={sub}>
                        {sub}
                      </option>
                    ))}
                  </select>

                  <input
                    value={newSubCategory}
                    onChange={(e) => setNewSubCategory(e.target.value)}
                    placeholder="Nouvelle sous-catégorie"
                    className="p-2 border rounded w-full mb-2"
                  />
                  <button
                    onClick={addSubCategory}
                    className="bg-green-500 text-white px-4 py-2 rounded w-full mb-4"
                  >
                    ➕ Ajouter la sous-catégorie
                  </button>

                  <ul className="mb-8">
                    {subCategories.map((sub, idx) => (
                      <li key={idx} className="flex justify-between items-center border-b py-1">
                        <span>{sub}</span>
                        <button
                          onClick={() => deleteSubCategory(sub)}
                          className="text-red-600 hover:text-red-800"
                        >
                          Supprimer
                        </button>
                      </li>
                    ))}
                  </ul>
                </>
              )}

              {selectedCategory && selectedSubCategory && (
                <div>
                  <h2 className="text-2xl font-semibold mb-2">📜 Canevas</h2>
                  <input
                    value={newCanevasTitle}
                    onChange={(e) => setNewCanevasTitle(e.target.value)}
                    placeholder="Titre du canevas"
                    className="p-2 border rounded w-full mb-2"
                  />
                  <textarea
                    value={newCanevasContent}
                    onChange={(e) => setNewCanevasContent(e.target.value)}
                    placeholder="Contenu"
                    className="p-2 border rounded w-full mb-2"
                    rows={4}
                  />
                  <button
                    onClick={addCanevas}
                    className="bg-blue-500 text-white px-4 py-2 rounded w-full"
                  >
                    ➕ Ajouter le canevas
                  </button>

                  <ul className="mt-4">
                    {canevasList.map((canevas) => (
                      <li key={canevas.id} className="border-b py-2">
                        {editingCanevasId === canevas.id ? (
                          <div>
                            <input
                              value={editedTitle}
                              onChange={(e) => setEditedTitle(e.target.value)}
                              className="p-2 border rounded w-full mb-2"
                            />
                            <textarea
                              value={editedContent}
                              onChange={(e) => setEditedContent(e.target.value)}
                              className="p-2 border rounded w-full mb-2"
                              rows={3}
                            />
                            <div className="flex gap-2">
                              <button
                                onClick={saveCanevasChanges}
                                className="bg-green-500 text-white px-4 py-1 rounded"
                              >
                                ✅ Sauvegarder
                              </button>
                              <button
                                onClick={cancelEditing}
                                className="bg-gray-500 text-white px-4 py-1 rounded"
                              >
                                ❌ Annuler
                              </button>
                            </div>
                          </div>
                        ) : (
                          <div className="flex justify-between items-center">
                            <div>
                              <strong>{canevas.title}</strong>
                            </div>
                            <div className="flex gap-2">
                              <button
                                onClick={() => startEditing(canevas)}
                                className="text-blue-600 hover:text-blue-800"
                              >
                                Modifier
                              </button>
                              <button
                                onClick={() => deleteCanevas(canevas.id)}
                                className="text-red-600 hover:text-red-800"
                              >
                                Supprimer
                              </button>
                            </div>
                          </div>
                        )}
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </motion.div>
          )}
        </AnimatePresence>

        {/* Suggestions */}
        <AnimatePresence>
          {showSuggestionsSection && (
            <motion.div
              key="suggestions-section"
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: "auto" }}
              exit={{ opacity: 0, height: 0 }}
              transition={{ duration: 0.3 }}
              className="mt-6 overflow-hidden bg-gray-50 border p-4 rounded"
            >
              <h2 className="text-xl font-semibold mb-4 text-blue-700">📨 Suggestions reçues</h2>
              {suggestions.length === 0 ? (
                <p className="text-gray-500 italic">Aucune suggestion pour le moment.</p>
              ) : (
                <ul className="space-y-4">
                  {suggestions.map((sugg) => (
                    <li key={sugg.id} className="border-b pb-3">
                      <div className="text-sm text-gray-600 mb-1">
                        <strong>Type :</strong> {sugg.category} | <strong>Par :</strong>{" "}
                        {sugg.users?.email || "Inconnu"}
                      </div>
                      <p className="text-gray-800 mb-2">{sugg.content}</p>
                      <div className="text-xs text-gray-500 mb-2">
                        Reçue le {new Date(sugg.created_at).toLocaleString("fr-CA")}
                      </div>
                      <button
                        onClick={() => deleteSuggestion(sugg.id)}
                        className="text-sm bg-red-500 text-white px-3 py-1 rounded hover:bg-red-600"
                      >
                        Supprimer
                      </button>
                    </li>
                  ))}
                </ul>
              )}
            </motion.div>
          )}
        </AnimatePresence>

        {/* News */}
        <AnimatePresence>
          {showNewsSection && (
            <motion.div
              key="news-section"
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: "auto" }}
              exit={{ opacity: 0, height: 0 }}
              transition={{ duration: 0.3 }}
              className="mt-6 overflow-hidden bg-gray-50 border p-4 rounded"
            >
              <h2 className="text-xl font-semibold mb-4 text-blue-700">🆕 Quoi de neuf ?</h2>
              <div className="mb-4">
                <input
                  type="text"
                  placeholder="Titre de la nouveauté"
                  value={newNewsTitle}
                  onChange={(e) => setNewNewsTitle(e.target.value)}
                  className="w-full p-2 border rounded mb-2"
                />
                <textarea
                  placeholder="Contenu"
                  value={newNewsContent}
                  onChange={(e) => setNewNewsContent(e.target.value)}
                  className="w-full p-2 border rounded mb-2"
                  rows={4}
                />
                <button
                  onClick={async () => {
                    if (!newNewsTitle.trim() || !newNewsContent.trim()) {
                      alert("Titre et contenu requis.");
                      return;
                    }
                    const { error } = await supabase.from("news").insert([
                      { title: newNewsTitle, content: newNewsContent },
                    ]);
                    if (error) {
                      console.error(error);
                      alert("❌ Erreur");
                      return;
                    }
                    alert("✅ Nouvelle ajoutée !");
                    setNewNewsTitle("");
                    setNewNewsContent("");
                    fetchNews();
                  }}
                  className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700"
                >
                  Ajouter
                </button>
              </div>

              <hr className="my-4" />

              {newsList.length === 0 ? (
                <p className="text-gray-500 italic">Aucune nouveauté pour le moment.</p>
              ) : (
                <ul className="space-y-4">
                  {newsList.map((news) => (
                    <li key={news.id} className="border-b pb-3 flex justify-between items-start">
                      <div>
                        <p className="font-bold">{news.title}</p>
                        <p className="text-gray-700">{news.content}</p>
                        <p className="text-xs text-gray-500 mt-1">
                          Publié le {new Date(news.created_at).toLocaleString("fr-CA")}
                        </p>
                      </div>
                      <button
                        onClick={async () => {
                          const confirmDelete = window.confirm("⚠️ Supprimer cette nouveauté ?");
                          if (!confirmDelete) return;

                          const { error } = await supabase.from("news").delete().eq("id", news.id);
                          if (error) {
                            console.error(error);
                            alert("❌ Erreur lors de la suppression");
                            return;
                          }
                          alert("🗑️ Nouvelle supprimée !");
                          fetchNews();
                        }}
                        className="ml-4 text-sm bg-red-500 text-white px-3 py-1 rounded hover:bg-red-600"
                      >
                        Supprimer
                      </button>
                    </li>
                  ))}
                </ul>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* ✅ MODAL "TAPER SUPPRIMER" */}
      {confirmOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg shadow-xl w-full max-w-lg p-6">
            <h3 className="text-xl font-bold mb-2 text-red-700">{confirmInfo.title}</h3>

            <p className="whitespace-pre-line text-gray-700 mb-4">{confirmInfo.message}</p>

            <input
              value={confirmText}
              onChange={(e) => setConfirmText(e.target.value)}
              placeholder='Tapez "SUPPRIMER"'
              className="w-full border rounded p-2 mb-2"
            />

            {confirmError && <div className="text-sm text-red-600 mb-2">{confirmError}</div>}

            <div className="flex gap-2 justify-end">
              <button
                onClick={closeConfirm}
                className="px-4 py-2 rounded bg-gray-200 hover:bg-gray-300"
              >
                Annuler
              </button>

              <button
                onClick={async () => {
                  if (confirmText.trim().toUpperCase() !== "SUPPRIMER") {
                    setConfirmError('Vous devez taper exactement "SUPPRIMER".');
                    return;
                  }
                  await confirmInfo.onConfirm();
                }}
                className="px-4 py-2 rounded bg-red-600 text-white hover:bg-red-700"
              >
                Confirmer
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default AdminPage;
